import {presentationPreferences} from './presentation.js';
// A presentation-only, once-per-tab opening. Never reads or writes career data.
let current=null;
const sessionKey=()=>`touchline.opening.${new URLSearchParams(location.search).has('qa')?'qa':'normal'}.v1`;
export function showOpeningIntro({returnFocus=null}={}){
 if(current)return;
 const previous=returnFocus||document.activeElement,media=matchMedia('(prefers-reduced-motion: reduce)');let reduced=media.matches||document.body.classList.contains('motion-off'),scene=null,paused=false;
 const dialog=document.createElement('dialog');dialog.className='opening-intro';dialog.dataset.stage='boot';dialog.dataset.layout='stage';dialog.setAttribute('aria-labelledby','opening-title');dialog.tabIndex=-1;
 dialog.innerHTML=`<div class="opening-backdrop" aria-hidden="true"><div class="opening-art"></div><div class="opening-shade"></div></div><div class="opening-stage" aria-hidden="true"><canvas tabindex="-1"></canvas><div class="opening-beat"><span>TOUCHLINE STUDIO / 10</span><strong>01 / FIRST TOUCH</strong></div></div><div class="opening-veil" aria-hidden="true"></div><header class="opening-header"><span>TOUCHLINE / FOOTBALL SANDBOX</span><div class="opening-actions"><button type="button" data-opening-motion aria-pressed="false" hidden>Pause animation</button><button type="button" data-opening-skip>Skip intro <span aria-hidden="true">↗</span></button></div></header><div class="opening-centre"><p class="opening-eyebrow">THE MATCH IS ONLY THE BEGINNING.</p><h1 id="opening-title">TOUCH<span>LINE</span><i aria-hidden="true"></i></h1><p class="opening-motto">YOUR CLUB. YOUR CALL.</p><button type="button" class="opening-enter" hidden>Enter Touchline <span aria-hidden="true">↗</span></button></div><footer class="opening-footer"><div class="opening-loading"><label for="opening-progress">Preparing local presentation</label><progress id="opening-progress" max="3" value="0"></progress></div><p class="opening-status" role="status">Loading stadium, typography and player model…</p><span>INDEPENDENT FOOTBALL · SAVED ON YOUR DEVICE</span></footer>`;
 dialog.querySelector("canvas").addEventListener("openingphase",event=>{const labels={dribble:"01 / FIRST TOUCH",receive:"02 / COMPOSURE","wind-up":"03 / COMMITMENT",shoot:"03 / COMMITMENT","follow-through":"03 / COMMITMENT",celebrate:"04 / THE MOMENT",settle:"YOUR NEXT CHAPTER",idle:"YOUR NEXT CHAPTER"};dialog.querySelector(".opening-beat strong").textContent=labels[event.detail]||"YOUR NEXT CHAPTER";});
 document.body.append(dialog);current=dialog;document.body.dataset.opening='boot';
 let timer,deadline,finished=false,count=0,failed=false;
 const enter=dialog.querySelector('.opening-enter'),status=dialog.querySelector('.opening-status'),motion=dialog.querySelector('[data-opening-motion]');
 const syncMotion=()=>{motion.hidden=reduced||!dialog.classList.contains('has-3d')||dialog.dataset.stage!=='title';motion.textContent=paused?'Play animation':'Pause animation';motion.setAttribute('aria-pressed',String(paused));};
 function title(){if(finished||dialog.dataset.stage==='title')return;clearTimeout(timer);dialog.dataset.stage='title';document.body.dataset.opening='title';dialog.querySelector('.opening-loading').hidden=true;status.textContent=failed?'Presentation asset unavailable. You can still enter the game.':'Ready when you are. Press Enter or tap below.';enter.hidden=false;syncMotion();scene?.start();enter.focus({preventScroll:true});}
 function close(){if(finished)return;finished=true;clearTimeout(timer);clearTimeout(deadline);media.removeEventListener('change',onMotionChange);scene?.dispose();document.removeEventListener('keydown',keyboard,true);dialog.close();dialog.remove();current=null;document.body.dataset.opening='complete';const target=previous?.isConnected&&previous!==document.body?previous:document.querySelector('#main');target?.focus({preventScroll:true});}
 function keyboard(e){if(e.key==='Tab'){const buttons=[...dialog.querySelectorAll('button')].filter(b=>!b.hidden),index=buttons.indexOf(document.activeElement);e.preventDefault();e.stopImmediatePropagation();buttons[(index+(e.shiftKey?-1:1)+buttons.length)%buttons.length].focus();return;}if(!['Escape','Enter',' '].includes(e.key))return;if(e.key!=='Escape'&&e.target.closest?.('[data-opening-motion]'))return;e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape'||e.target.closest?.('[data-opening-skip]'))close();else if(dialog.dataset.stage==='boot')title();else close();}
 function onMotionChange(){const focused=document.activeElement===motion;reduced=media.matches||document.body.classList.contains('motion-off');scene?.setReduced(reduced);syncMotion();if(motion.hidden&&focused)enter.focus({preventScroll:true});}
 media.addEventListener('change',onMotionChange);motion.addEventListener('click',()=>{paused=!paused;scene?.setPaused(paused);syncMotion();});
 dialog.querySelector('[data-opening-skip]').addEventListener('click',close);enter.addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 document.addEventListener('keydown',keyboard,true);dialog.showModal();dialog.focus({preventScroll:true});
 try{sessionStorage.setItem(sessionKey(),'seen');}catch{/* Storage-disabled browsers still allow skipping. */}
 const started=performance.now();
 function settled(ok){if(finished)return;failed||=!ok;dialog.querySelector('progress').value=++count;if(count===3){clearTimeout(deadline);timer=setTimeout(title,reduced?0:Math.max(0,1650-(performance.now()-started)));}}
 const art=new Image();art.onload=()=>{if(art.decode)art.decode().then(()=>settled(true),()=>settled(false));else settled(true);};art.onerror=()=>settled(false);art.src=new URL('./assets/studio-pitch.svg',import.meta.url).href;
 Promise.resolve(document.fonts?.ready).then(()=>settled(true),()=>settled(false));
 const unavailable=()=>{if(finished)return;const focused=document.activeElement===motion;dialog.classList.remove('has-3d');dialog.dataset.model='fallback';syncMotion();if(focused)enter.focus({preventScroll:true});if(dialog.dataset.stage==='title')status.textContent='The animated scene is unavailable. You can still enter Touchline.';};
 import('./opening-3d.js').then(async({OpeningScene})=>{if(finished)return;scene=new OpeningScene(dialog.querySelector('canvas'),{reduced,quality:presentationPreferences().quality,onUnavailable:unavailable});const ready=await scene.ready;if(finished)return;if(ready){dialog.classList.add('has-3d');dialog.dataset.model='ready';syncMotion();if(dialog.dataset.stage==='title')scene.start();}else unavailable();settled(ready);}).catch(()=>{if(!finished){unavailable();settled(false);}});
 deadline=setTimeout(()=>{failed=true;title();},5000);
}
export function startOpeningIntro(){let seen=false;try{seen=sessionStorage.getItem(sessionKey())==='seen';}catch{}if(seen)document.body.dataset.opening='complete';else showOpeningIntro();}
